export const adv2Materials: AuthoredMaterial[] = [
  { id: "jee-adv-phy-current-electricity-m01", topicId: "jee-adv-phy-current-electricity", title: "Current Electricity & DC Circuits", content: `**Ohm's law** V = IR; resistivity ρ relates R = ρL/A. Resistances add in **series** (R = ΣRᵢ) and combine reciprocally in **parallel** (1/R = Σ1/Rᵢ). **Kirchhoff's laws**: the junction rule (ΣI = 0, charge conservation) and loop rule (ΣV = 0, energy conservation) solve networks. A real cell has **EMF ε and internal resistance r**: terminal voltage V = ε − Ir. **Power** dissipated is P = I²R = V²/R = VI. **Drift velocity** v_d = eEτ/m links microscopic motion to current I = neAv_d. The **Wheatstone bridge** is balanced when P/Q = R/S; the **potentiometer** measures EMF without drawing current.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-phy-ray-optics-m01", topicId: "jee-adv-phy-ray-optics", title: "Ray Optics & Optical Instruments", content: `**Reflection** and the **mirror formula** 1/v + 1/u = 1/f (with magnification m = −v/u). **Refraction** follows Snell's law μ₁sinθ₁ = μ₂sinθ₂; **total internal reflection** occurs beyond the critical angle (sinθc = 1/μ), the basis of optical fibres. The **lens formula** 1/v − 1/u = 1/f and the **lensmaker's equation** 1/f = (μ−1)(1/R₁ − 1/R₂); power P = 1/f in dioptres, and lenses in contact add powers. A **prism** deviates light (minimum deviation gives μ = sin[(A+δm)/2]/sin(A/2)) and disperses it. Instruments: the compound microscope and telescope with magnifying power formulas.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-phy-kinetic-theory-m01", topicId: "jee-adv-phy-kinetic-theory", title: "Kinetic Theory of Gases", content: `Gas pressure arises from molecular collisions: **P = (1/3)ρv̄² = (1/3)(nm/V)v̄²**. The **average translational KE per molecule = (3/2)kT**, so temperature is a measure of molecular energy. Molecular speeds: **v_rms = √(3RT/M) > v_avg = √(8RT/πM) > v_mp = √(2RT/M)**. The **equipartition theorem** gives ½kT per degree of freedom, so internal energy and γ = Cp/Cv depend on degrees of freedom (monatomic 3 → γ = 5/3; diatomic 5 → γ = 7/5). The **mean free path** λ = 1/(√2 πd²n) falls with pressure and molecular size. Real gases deviate at high P and low T.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-phy-laws-friction-m01", topicId: "jee-adv-phy-laws-friction", title: "Newton's Laws & Friction", content: `**Newton's laws**: (1) inertia; (2) F = ma = dp/dt; (3) action–reaction on different bodies. **Momentum** is conserved when the net external force is zero, and **impulse** = ∫F dt = Δp. **Friction**: limiting static friction f_s ≤ μ_s N and kinetic friction f_k = μ_k N (usually μ_k < μ_s), independent of contact area. On an incline, a block just slides when tanθ = μ_s (angle of repose). **Circular motion** needs centripetal force mv²/r; on a level road the maximum safe speed is √(μrg), improved by **banking** (tanθ = v²/rg). Pseudo-forces (magnitude ma) appear in non-inertial frames.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-atomic-structure-m01", topicId: "jee-adv-chem-atomic-structure", title: "Atomic Structure & Quantum Numbers", content: `Bohr's model gives hydrogen energy Eₙ = −13.6/n² eV and radius rₙ ∝ n²; the **Rydberg formula** predicts spectral lines. **Quantum numbers**: principal n (shell/energy), azimuthal l (subshell/shape, 0…n−1), magnetic mₗ (orientation, −l…+l), and spin mₛ (±½). Orbitals fill by the **Aufbau principle**, **Pauli exclusion principle**, and **Hund's rule** (maximum multiplicity). **Heisenberg's uncertainty principle** limits simultaneous position and momentum. The **de Broglie wavelength** λ = h/p and the shapes of s, p, d orbitals (with nodes: radial n−l−1, angular l) are key. Half- and fully-filled subshells (Cr, Cu) show extra stability.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-hydrocarbons-m01", topicId: "jee-adv-chem-hydrocarbons", title: "Hydrocarbons", content: `**Alkanes** (CₙH₂ₙ₊₂, sp³) undergo free-radical **halogenation** (chain mechanism). **Alkenes** (CₙH₂ₙ, sp²) undergo **electrophilic addition** obeying **Markovnikov's rule** (anti-Markovnikov with peroxides), plus ozonolysis and hydroboration. **Alkynes** (CₙH₂ₙ₋₂, sp) are weakly acidic at terminal C–H. **Aromatics** (benzene, sp², delocalised π, Hückel's 4n+2 rule) undergo **electrophilic aromatic substitution** (nitration, halogenation, Friedel–Crafts alkylation/acylation, sulphonation); substituents are activating o/p-directors (−OH, −NH₂, −R) or deactivating m-directors (−NO₂, −COOH). Conformations of ethane/cyclohexane (chair) and reaction mechanisms are Advanced favourites.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-d-f-block-m01", topicId: "jee-adv-chem-d-f-block", title: "d- & f-Block Elements", content: `**Transition metals** have partially filled d-orbitals, giving **variable oxidation states, coloured ions (d–d transitions), paramagnetism** (μ = √(n(n+2)) BM), **catalytic activity**, complex and alloy formation, and interstitial compounds. Across a period, atomic radii are similar; the **lanthanoid contraction** (steady 4f-series decrease) makes 4d and 5d elements (e.g., Zr/Hf) nearly identical in size. **KMnO₄** (Mn⁷⁺) and **K₂Cr₂O₇** (Cr⁶⁺) are important oxidising agents with distinctive redox chemistry. **f-block**: lanthanoids (+3 typical) and actinoids (all radioactive, variable states). Zn, Cd, Hg (d¹⁰) are not typical transition metals.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-chem-alcohols-phenols-ethers-m01", topicId: "jee-adv-chem-alcohols-phenols-ethers", title: "Alcohols, Phenols & Ethers", content: `**Alcohols** (R–OH) are prepared by hydration of alkenes, reduction of carbonyls, and from Grignard reagents. Oxidation: 1° → aldehyde → acid, 2° → ketone, 3° resists oxidation. **Phenols** are more acidic than alcohols because the **phenoxide ion is resonance-stabilised**; electron-withdrawing groups (–NO₂) increase acidity. Phenol undergoes ring reactions (Kolbe, Reimer–Tiemann, bromination) readily. **Ethers** (R–O–R′) are made by the **Williamson synthesis** (alkoxide + 1° alkyl halide, SN2) and cleave with HI/HBr. Distinguishing tests (Lucas, Victor Meyer) and named reactions are common in Advanced problems.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-quadratic-equations-m01", topicId: "jee-adv-math-quadratic-equations", title: "Quadratic & Theory of Equations", content: `For ax² + bx + c = 0, roots are x = [−b ± √(b²−4ac)]/2a; **sum = −b/a**, **product = c/a**. The **discriminant** D = b²−4ac decides the nature: D > 0 real distinct, D = 0 real equal, D < 0 complex conjugate. Complex/irrational roots occur in conjugate pairs (real coefficients). The **sign of a quadratic** and its **maximum/minimum** (vertex at x = −b/2a) solve inequalities and range problems. For higher polynomials, **Vieta's formulas** relate symmetric functions of roots to coefficients; common roots, transformation of equations, and location of roots (using f(α)·f(β) < 0) are Advanced staples.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-coordinate-geometry-m01", topicId: "jee-adv-math-coordinate-geometry", title: "Straight Lines & Circles", content: `A line's **slope** m = tanθ; forms include slope-intercept y = mx + c, point-slope, and two-point. **Parallel** lines have equal slopes; **perpendicular** lines have m₁m₂ = −1. The **distance** from a point to ax + by + c = 0 is |ax₀+by₀+c|/√(a²+b²). A **circle** (x−h)² + (y−k)² = r² or x² + y² + 2gx + 2fy + c = 0 has centre (−g,−f) and radius √(g²+f²−c). A line is **tangent** when the perpendicular distance from the centre equals r. **Family of lines/circles**, angle between lines (tanθ = |(m₁−m₂)/(1+m₁m₂)|), and the radical axis of two circles are recurring Advanced tools.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-trigonometry-m01", topicId: "jee-adv-math-trigonometry", title: "Trigonometry", content: `The **Pythagorean identities** sin²θ + cos²θ = 1, 1 + tan²θ = sec²θ, 1 + cot²θ = cosec²θ. **Compound angles**: sin(A±B), cos(A±B), tan(A±B); **double/triple angles** (sin2θ = 2 sinθ cosθ, cos2θ = 1−2sin²θ). **Product-to-sum** and **sum-to-product** formulas simplify expressions. **General solutions** of trig equations: sinθ = sinα → θ = nπ + (−1)ⁿα; cosθ = cosα → θ = 2nπ ± α; tanθ = tanα → θ = nπ + α. In triangles, the **sine rule** a/sinA = 2R and the **cosine rule** c² = a² + b² − 2ab cosC apply. Inverse-trig principal ranges and identities round out the topic.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "jee-adv-math-functions-m01", topicId: "jee-adv-math-functions", title: "Relations & Functions", content: `A **function** maps each domain element to exactly one image. Types: **injective** (one-one), **surjective** (onto), **bijective** (both, hence invertible). Find **domain and range** by considering restrictions (denominators, even roots, logs). **Composite** functions (f∘g)(x) = f(g(x)) and **inverse** functions (exist iff bijective; graph reflects over y = x). Special functions: modulus, greatest-integer, signum, and **even/odd** functions (f(−x) = f(x) or −f(x)). **Periodic** functions repeat with a fundamental period. An **equivalence relation** is reflexive, symmetric, and transitive. These underpin much of Advanced calculus and algebra.`, estimatedReadTime: 2, orderIndex: 0 }
];

